'use client';

import type { Template } from '@/templates/generated';
import { DIRECTOR_ERRORS, DIRECTOR_TEXT, PROVIDER_LABELS } from '../consts/director.consts';
import type { DirectorState } from '../hooks/use-director';
import type { ProviderId } from '../interfaces/director.interfaces';

interface DirectorPanelProps {
  director: DirectorState;
  /** The template the world currently renders (its `meta.generatedBy` drives the label). */
  template: Template;
}

/** Provider selector, "Generate world with AI" and the "generated by" label. Text only: no HTML from the model. */
export function DirectorPanel({ director, template }: DirectorPanelProps) {
  const { providers, provider, setProvider, generate, status, errorKey, results } = director;
  const generatedBy = template.meta?.generatedBy ?? null;
  const result = results.find((r) => r.template.id === template.id) ?? null;
  const busy = status === 'loading' || status === 'generating';
  return (
    <section
      aria-label={DIRECTOR_TEXT.title}
      className="flex w-full flex-col gap-2 rounded-lg bg-[var(--mw-bg)]/80 p-3 text-sm sm:w-80"
    >
      <div className="flex flex-wrap items-center gap-2">
        <label htmlFor="director-provider" className="sr-only">
          {DIRECTOR_TEXT.provider}
        </label>
        <select
          id="director-provider"
          className="min-w-0 flex-1 rounded border border-white/20 bg-transparent px-2 py-1"
          value={provider}
          disabled={busy}
          onChange={(event) => setProvider(event.target.value as ProviderId)}
        >
          {providers.map((p) => (
            <option key={p.id} value={p.id} className="bg-[var(--mw-bg)]">
              {PROVIDER_LABELS[p.id]}
            </option>
          ))}
        </select>
        <button
          type="button"
          onClick={generate}
          disabled={busy}
          className="rounded bg-[var(--mw-primary)] px-3 py-1 font-medium disabled:opacity-50"
        >
          {DIRECTOR_TEXT.generate}
        </button>
      </div>
      {status === 'generating' && <p role="status">{DIRECTOR_TEXT.generating}</p>}
      {status === 'error' && (
        <p role="alert" className="text-[var(--mw-accent)]">
          {DIRECTOR_ERRORS[errorKey ?? 'UNKNOWN'] ?? DIRECTOR_ERRORS.UNKNOWN}
        </p>
      )}
      {generatedBy && (
        <p data-testid="generated-by" className="opacity-80">
          {DIRECTOR_TEXT.generatedBy(PROVIDER_LABELS[generatedBy.provider], generatedBy.model)}
          {result?.cached ? ` (${DIRECTOR_TEXT.cached})` : ''}
        </p>
      )}
      {result && result.provider !== result.requestedProvider && (
        <p className="text-xs opacity-60">
          {DIRECTOR_TEXT.fallback(PROVIDER_LABELS[result.requestedProvider], PROVIDER_LABELS[result.provider])}
        </p>
      )}
    </section>
  );
}
